begin;
set local statement_timeout='20s';
set local lock_timeout='1s';
set local idle_in_transaction_session_timeout='25s';
set local search_path='';

do $admit$
declare fixture_owner_id uuid:=nullif(current_setting('resumide.fixture_owner_id',true),'')::uuid;
  fixture_analysis_id uuid:=nullif(current_setting('resumide.fixture_analysis_id',true),'')::uuid;
  acknowledged text:=current_setting('resumide.native_fixture_allocation',true); signature text; ready jsonb;
begin
  if fixture_owner_id is null or fixture_analysis_id is null or acknowledged is distinct from 'a12-owned-synthetic-rollback' then
    raise exception 'A12_NATIVE_FIXTURE_ADMISSION_REQUIRED';end if;
