  if ready->>'schemaVersion' is distinct from 'canonical-rewrite-readiness/1.0.0'
    or ready->'schemaReady' is distinct from 'true'::jsonb or ready->'mutatorsExecutable' is distinct from 'false'::jsonb then
    raise exception 'A12_STAGED_SCHEMA_REQUIRED';end if;
  foreach signature in array array['public.prepare_canonical_rewrite(uuid,uuid,jsonb,text)',
    'public.claim_canonical_rewrite_dispatch(uuid,uuid,uuid,text,jsonb)',
    'public.finish_canonical_rewrite(uuid,uuid,uuid,text,jsonb,jsonb,text)',
    'public.settle_canonical_rewrite_attempt(uuid,uuid,uuid,text,jsonb,text)'] loop
    if has_function_privilege('service_role',to_regprocedure(signature),'EXECUTE')
