,"start":0,"end":61,"quote":"At least 4 years of Python and PostgreSQL experience required"},"confidence":{"kind":"uncalibrated","value":null},"mapping":null,"tokenEvidence":[]},{"id":"b78021b6-a208-450d-bece-9cce24e08f55","type":"skill","value":"Python","importance":"required","importanceBasis":"explicit","importanceEvidence":{"start":0,"end":61,"quote":"At least 4 years of Python and PostgreSQL experience required"},"derivation":"exact","minimumYears":null,"negated":false,"ambiguity":[],"dedupGroup":"27c4eee33285140e1bad2e3f1175b31afd8aaaadc8bcd458cc0836e5fe4bc173","evidence":{"spanId":"jd-0-61","start":0,"end":61,"quote":"At least 4 years of Python and PostgreSQL experience required"},"confidence":{"kind":"uncalibrated","value":null},"mapping":{"kind":"unmapped","policyVersion":"jd-local-aliases/1.0.0","conceptId":null,"canonicalValue":null,"prospectiveCreditGroup":null},"tokenEvidence":[{"spanId":"jd-20-26","start":20,"end":26,"quote":"Python"}]},{"id":"5f727637-6763-4f03-94d2-be70353f11c5","type":"skill","value":"PostgreSQL","importance":"required","importanceBasis":"explicit","importanceEvidence":{"start":0,"end":61,"quote":"At least 4 years of Python and PostgreSQL experience required"},"derivation":"exact","minimumYears":null,"negated":false,"ambiguity":[],"dedupGroup":"052be4116f0d920c2178392a58f00e128b33488a25dc542155e967c788c9a373","evidence":{"spanId":"jd-0-61","start":0,"end":61,"quote":"At least 4 years of Python and PostgreSQL experience required"},"confidence":{"kind":"uncalibrated","value":null},"mapping":{"kind":"exact","policyVersion":"jd-local-aliases/1.0.0","conceptId":"local-software:postgresql","canonicalValue":"PostgreSQL","prospectiveCreditGroup":"22e7c117764a257dad78c41cf7ee0eebc38fb6400c35eee0700931a1a5e0a4be"},"tokenEvidence":[{"spanId":"jd-31-41","start":31,"end":41,"quote":"PostgreSQL"}]}],"retainedClauses":[{"evidence":{"spanId":"jd-0-61","start":0,"end":61,"quote":"At least 4 years of Python and PostgreSQL experience required"},"importance":"required","negated":false,"interpretation":"partial_vocabulary","reviewRequired":true,"requirementIds":["bc21d618-114d-44f3-b5b6-210a0f4df13a","b78021b6-a208-450d-bece-9cce24e08f55","5f727637-6763-4f03-94d2-be70353f11c5"]}],"relations":{"clauses":[{"id":"595f6592837308882231accfdc25b490fd04474a68ac7b78ba41635474bf31c3","evidence":{"spanId":"jd-0-61","start":0,"end":61,"quote":"At least 4 years of Python and PostgreSQL experience required"},"reviewRequired":true,"scope":{"importance":"required","negated":false},"skillExpression":{"kind":"unknown","reason":"unparsed_scope_or_operand_review","evidence":{"spanId":"jd-0-61","start":0,"end":61,"quote":"At least 4 years of Python and PostgreSQL experience required"},"observedRequirementIds":["bc21d618-114d-44f3-b5b6-210a0f4df13a","b78021b6-a208-450d-bece-9cce24e08f55","5f727637-6763-4f03-94d2-be70353f11c5"]},"duration":{"kind":"at_least","evidence":{"spanId":"jd-0-16","start":0,"end":16,"quote":"At least 4 years"},"lower":{"value":4,"inclusive":true,"evidence":{"spanId":"jd-9-10","start":9,"end":10,"quote":"4"}},"upper":null,"operatorEvidence":[{"spanId":"jd-0-8","start":0,"end":8,"quote":"At least"}],"candidateEvidence":[{"spanId":"jd-0-16","start":0,"end":16,"quote":"At least 4 years"}],"reason":null,"subjectBinding":"literal_clause_only","evaluated":false},"prospectiveCreditGroups":["22e7c117764a257dad78c41cf7ee0eebc38fb6400c35eee0700931a1a5e0a4be"],"numericCredit":null}]},"warnings":["uncalibrated_requirements","domain_pack_review_pending","local_alias_policy_not_admitted","clause_interpretation_review_pending"]},"expressions":[]}]$vectors$::jsonb; v jsonb; actual jsonb;
begin
  for v in select value from jsonb_array_elements(vectors) loop
    if private.job_requirement_relations_valid(v->'document') is not true then raise exception 'A12_ACTUAL_JD_VECTOR_INVALID';end if;
    select coalesce(jsonb_agg(value->'skillExpression'),'[]') into actual from jsonb_array_elements(private.canonical_rewrite_effective_clauses(v->'document'));
    if actual is distinct from v->'expressions' then raise exception 'A12_DURATION_SUBJECT_PARITY';end if;
  end loop;
end;
$duration_parity$;

do $owned_cases$
declare fixture_owner_id uuid:=current_setting('resumide.fixture_owner_id')::uuid;
  fixture_analysis_id uuid:=current_setting('resumide.fixture_analysis_id')::uuid;
  fixture_org_id uuid; op_id uuid:=gen_random_uuid(); second_id uuid:=gen_random_uuid(); ctx jsonb; initial_ctx jsonb;
  policy jsonb:=jsonb_build_object('version','canonical-rewrite-rules/1.0.0','sha256','648e65d09340f4bd0b6ef36aa9c3799b883f6d41211883a238e6c222381d536f',
    'promptVersion','canonical-closed-rewrite/1.0.0','writingSupportVersion','legacy-source-transforms/1.0.4','model','synthetic-model');
  request_value jsonb; command_value jsonb; prepared jsonb; claimed jsonb; repeated jsonb; settlement jsonb;
  plan jsonb; publication jsonb; replay jsonb; exported jsonb; usage_value jsonb:=jsonb_build_object('inputTokens','10','outputTokens','2');
  baseline_runs integer; baseline_versions integer; old_projection jsonb; old_updated timestamptz; current_projection jsonb;
  failed boolean;
begin
  select organization_id into strict fixture_org_id from public.analyses where id=fixture_analysis_id and owner_id=fixture_owner_id;
  -- The fixture is expressly synthetic; this temporary consent is rolled back.
  insert into public.consents(organization_id,user_id,purpose,policy_version)
    values(fixture_org_id,fixture_owner_id,'qualitative_ai','candidate-ai-v1') on conflict(user_id,purpose,policy_version) do nothing;
  initial_ctx:=public.read_canonical_rewrite_context(fixture_owner_id,fixture_analysis_id,
    jsonb_build_object('canonicalVersionId',null,'requirementVersionId',null),policy);
  if jsonb_array_length(initial_ctx->'manifest')=0 then raise exception 'A12_REAL_SUPPORTED_FIXTURE_REQUIRED';end if;
  request_value:=jsonb_build_object('schemaVersion','canonical-rewrite-request/1.0.0','operationId',op_id,
    'canonicalVersionId',initial_ctx->'relationshipContext'->'canonical'->'versionId','requirementVersionId',initial_ctx->'relationshipContext'->'requirements'->'versionId',
    'draftId',initial_ctx->'draft'->'id','expectedDraftUpdatedAt',initial_ctx->'draft'->'updatedAt');
  command_value:=jsonb_build_object('schemaVersion','canonical-rewrite-command/1.0.0','request',request_value,'policy',policy);
  prepared:=public.prepare_canonical_rewrite(fixture_owner_id,fixture_analysis_id,command_value,op_id::text);ctx:=prepared->'context';
  repeated:=public.prepare_canonical_rewrite(fixture_owner_id,fixture_analysis_id,command_value,op_id::text);
  if repeated->'context' is distinct from 'null'::jsonb or repeated->'operation'->'dispatchAllowed' is distinct from 'false'::jsonb then raise exception 'A12_PREPARE_REPLAY';end if;
  select count(*) into baseline_runs from public.analysis_ai_runs where analysis_id=fixture_analysis_id;
  select count(*) into baseline_versions from private.canonical_rewrite_versions where analysis_id=fixture_analysis_id;
  select draft,updated_at into old_projection,old_updated from public.writer_drafts where id=(request_value->>'draftId')::uuid;
  claimed:=public.claim_canonical_rewrite_dispatch(fixture_owner_id,fixture_analysis_id,op_id,ctx->>'bindingSha256',null);
  repeated:=public.claim_canonical_rewrite_dispatch(fixture_owner_id,fixture_analysis_id,op_id,ctx->>'bindingSha256',null);
  if claimed->'operation'->'dispatchAllowed' is distinct from 'true'::jsonb or repeated->'operation'->'dispatchAllowed' is distinct from 'false'::jsonb
    or (select count(*) from public.analysis_ai_runs where analysis_id=fixture_analysis_id)<>baseline_runs then raise exception 'A12_ONCE_CLAIM_NO_PREMATURE_RUN';end if;
  settlement:=public.settle_canonical_rewrite_attempt(fixture_owner_id,fixture_analysis_id,op_id,ctx->>'bindingSha256',usage_value,null);
  if settlement->'usage' is distinct from usage_value then raise exception 'A12_KNOWN_USAGE_NOT_RECORDED';end if;
  failed:=false;
  begin
    perform public.finish_canonical_rewrite(fixture_owner_id,fixture_analysis_id,op_id,ctx->>'bindingSha256',
      jsonb_build_object('summarySourceId',null,'bullets',jsonb_build_array(jsonb_build_object('sourceId',0,'clauseId',ctx->'manifest'->0->'clauseIds'->0,'operation','copy','replacementAction',null,'unsupportedText','forbidden'))),usage_value,op_id::text);
  exception when invalid_parameter_value then failed:=true;end;
  if not failed or (select count(*) from public.analysis_ai_runs where analysis_id=fixture_analysis_id)<>baseline_runs
    or (select count(*) from private.canonical_rewrite_versions where analysis_id=fixture_analysis_id)<>baseline_versions
    or not exists(select 1 from public.writer_drafts where id=(request_value->>'draftId')::uuid and draft=old_projection and updated_at=old_updated)
    or not exists(select 1 from private.canonical_rewrite_operations where owner_id=fixture_owner_id and analysis_id=fixture_analysis_id and operation_id=op_id and usage=usage_value) then raise exception 'A12_REJECTED_OUTPUT_CHANGED_CONTENT_OR_LOST_USAGE';end if;
  plan:=jsonb_build_object('summarySourceId',null,'bullets',jsonb_build_array(jsonb_build_object('sourceId',0,'clauseId',ctx->'manifest'->0->'clauseIds'->0,'operation','copy','replacementAction',null)));
  publication:=public.finish_canonical_rewrite(fixture_owner_id,fixture_analysis_id,op_id,ctx->>'bindingSha256',plan,usage_value,op_id::text);
  replay:=public.finish_canonical_rewrite(fixture_owner_id,fixture_analysis_id,op_id,ctx->>'bindingSha256',plan,usage_value,op_id::text);
  if replay->'receipt' is distinct from (publication->'receipt'||jsonb_build_object('idempotent',true)) or replay->'result' is distinct from publication->'result'
    or (select count(*) from public.analysis_ai_runs where analysis_id=fixture_analysis_id)<>baseline_runs+1
    or (select count(*) from private.canonical_rewrite_versions where analysis_id=fixture_analysis_id)<>baseline_versions+1 then raise exception 'A12_PUBLICATION_REPLAY';end if;
  select draft into current_projection from public.writer_drafts where id=(request_value->>'draftId')::uuid;
  if publication->'receipt'->>'projectionSha256' is distinct from private.typed_authoring_sha256(current_projection::text)
    or publication->'receipt'->>'resultSha256' is distinct from private.typed_authoring_sha256((publication->'result')::text)
    or (publication->'receipt'->>'revision')::integer<>(ctx->'draft'->>'revision')::integer+1 then raise exception 'A12_NATIVE_PUBLICATION_CORRELATION';end if;
  ctx:=public.read_canonical_rewrite_context(fixture_owner_id,fixture_analysis_id,jsonb_build_object('canonicalVersionId',null,'requirementVersionId',null),policy);
  if ctx->'saved'->>'state' is distinct from 'current' or ctx->'saved'->'legacyDraft' is distinct from 'null'::jsonb then raise exception 'A12_FALSE_HISTORICAL_INPUT_DRAFT_COMPARE';end if;
  -- Fresh second operation: unknown spend retains its once-claim, never a retry.
  request_value:=request_value||jsonb_build_object('operationId',second_id,'expectedDraftUpdatedAt',ctx->'draft'->'updatedAt');
  prepared:=public.prepare_canonical_rewrite(fixture_owner_id,fixture_analysis_id,jsonb_build_object('schemaVersion','canonical-rewrite-command/1.0.0','request',request_value,'policy',policy),second_id::text);
  perform public.claim_canonical_rewrite_dispatch(fixture_owner_id,fixture_analysis_id,second_id,prepared->'operation'->>'bindingSha256',null);
  settlement:=public.settle_canonical_rewrite_attempt(fixture_owner_id,fixture_analysis_id,second_id,prepared->'operation'->>'bindingSha256',null,'unknown');
  if settlement->'usage' is distinct from 'null'::jsonb or settlement->>'state' is distinct from 'unknown' then raise exception 'A12_UNKNOWN_NOT_ZERO';end if;
  repeated:=public.claim_canonical_rewrite_dispatch(fixture_owner_id,fixture_analysis_id,second_id,prepared->'operation'->>'bindingSha256',null);
  if repeated->'operation'->'dispatchAllowed' is distinct from 'false'::jsonb then raise exception 'A12_UNKNOWN_REDISPATCH';end if;
  exported:=public.export_canonical_rewrite_records(fixture_owner_id);
  if exported->>'schemaVersion' is distinct from 'canonical-rewrite-export/1.0.0'
    or not exists(select 1 from jsonb_array_elements(exported->'canonicalRewriteOperations') x(value) where x.value->>'operation_id'=op_id::text)
    or not exists(select 1 from jsonb_array_elements(exported->'canonicalRewriteVersions') x(value) where x.value->'receipt'=publication->'receipt') then raise exception 'A12_EXPORT_OMISSION';end if;
  -- Actual two-session race/lock/CAS/privacy tests and budget-coupled claim are
  -- still REQUIRED in the separately admitted native protocol. Same-session
  -- owner locks here cannot demonstrate contention or snapshot-race safety.
  set constraints all immediate;
end;
$owned_cases$;
rollback;
